import { useTranslation } from "@fanfanlo";
import { Box, Button, Dialog, DialogActions, DialogContent, DialogContentText, DialogTitle, Typography } from "@mui/material";
import { useRouter } from "next/router";
import { useState } from "react";
import toast from "react-hot-toast";


export function AccountRemoveContent() {
  const { t } = useTranslation('homepage/components/account/remove/content');
  const router = useRouter();
  const [open, setOpen] = useState(false);

  const handleClickOpen = () => {
    setOpen(true);
  };

  const handleClose = () => {
    setOpen(false);
  };

  function removeAccount(){
    handleClose();
    toast(t('AccountRemoveContent.removingToast'), {icon: '⏳'});
    setTimeout(()=>{
      toast.success(t('AccountRemoveContent.removedToast'));
      setTimeout(()=>{
        back();
      }, 2500);
    }, 2000);
  }
  function back(){
    router.back();
  }
  return (<>
  <Box>
    <Box>
        <Typography variant="h6">{t('AccountRemoveContent.title')}</Typography>
    </Box>
    <Box>
        <Typography variant="body1" sx={{marginTop:2}}>{t('AccountRemoveContent.description')}</Typography>
    </Box>
    <Box>
        <Typography variant="body2" color="error" sx={{marginTop:2}}>{t('AccountRemoveContent.warning')}</Typography>
    </Box>
    <Box>
        <Button variant="contained" color="error" sx={{marginTop:4, marginRight:2}} onClick={handleClickOpen}>{t('AccountRemoveContent.confirmButton')}</Button>
    </Box>
  </Box>
  <Dialog
        open={open}
        onClose={handleClose}
        aria-labelledby="alert-dialog-title"
        aria-describedby="alert-dialog-description"
      >
        <DialogTitle id="alert-dialog-title">
          {t('AccountRemoveContent.dialogTitle')}
        </DialogTitle>
        <DialogContent>
          <DialogContentText id="alert-dialog-description">
            {t('AccountRemoveContent.confirmAsk')}
          </DialogContentText>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleClose}>{t('AccountRemoveContent.dialogConfirCancelButton')}</Button>
          <Button onClick={removeAccount} autoFocus>
            {t('AccountRemoveContent.dialogConfirmButton')}
          </Button>
        </DialogActions>
      </Dialog>
  </>)
}
